16	const PROCESSING_FEE = 5;
17	
18	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
19	
20	const BASE_PREMIUMS: Record<string, number> = {
21	  sword: 100,
22	  amulet: 60,
23	  staff: 80,
24	  potion: 40,
25	  rune: 25,
26	  moonstone: 25,
27	};
28	
29	// Every percentage modifier is a delta computed against an *unmodified* base
30	// and summed with the others — modifiers never compound. Policy-wide ones use
31	// the policy base, item-specific ones the affected item's own base premium.
32	//
33	// Percentages stay in integer percent points: multiply first, divide by 100
34	// last. A float multiplier such as `base * 1.1` yields 110.00000000000001 for
35	// a sword and breaks the ceil. `(base * 10) / 100` gives exactly 10.
36	const percentOf = (amount: number, percent: number): number =>
37	  (amount * percent) / 100;
38	
39	const BLOCK_SIZE = 3;
40	const BLOCK_BASE_PREMIUM = 60;
41	
42	const countByType = (items: Item[]): Map<string, number> => {
43	  const counts = new Map<string, number>();
44	
45	  for (const item of items) {
46	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
47	  }
48	
49	  return counts;
50	};
51	
52	const baseOfGroup = (type: string, count: number): number =>
53	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];
54	
55	const policyBaseOf = (items: Item[]): number =>
56	  [...countByType(items)].reduce(
57	    (total, [type, count]) => total + baseOfGroup(type, count),
58	    0,
59	  );
60	
61	// Policy-wide modifiers: each is a percentage of the policy base premium.
62	const policyModifiersOf = (policyBase: number): number =>
63	  percentOf(policyBase, FIRST_INSURANCE_SURCHARGE_PERCENT);
64	
65	const CURSE_SURCHARGE_PERCENT = 50;
66	
67	// Item-specific modifiers: each is a percentage of the affected item's own
68	// base premium.
69	const HIGH_ENCHANTMENT_THRESHOLD = 5;
70	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
71	
72	const itemModifiersOf = (item: Item): number => {
73	  const itemBase = BASE_PREMIUMS[item.type];
74	  const curse = item.cursed ? percentOf(itemBase, CURSE_SURCHARGE_PERCENT) : 0;
75	  const highEnchantment =
76	    (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD
77	      ? percentOf(itemBase, HIGH_ENCHANTMENT_SURCHARGE_PERCENT)
78	      : 0;
79	
80	  return curse + highEnchantment;
81	};
82	
83	const quote = (items: Item[]): number => {
84	  const policyBase = policyBaseOf(items);
85	  const modifiers =
86	    policyModifiersOf(policyBase) +
87	    items.reduce((total, item) => total + itemModifiersOf(item), 0);
88	
89	  // Rounding is in the MHPCO's favour: premiums round up.
90	  return Math.ceil(policyBase + modifiers) + PROCESSING_FEE;
91	};
92	
93	export const runScenario = (scenario: Scenario): ScenarioResult => ({
94	  results: scenario.steps.map((step) => ({ premium: quote(step.items) })),
95	});
